1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any
15	 * required owner field before {@link BuildOwner} runs, throwing {@link MissingFieldsException}
16	 * (handled as a 400 listing the offending field names). Normalizes the telephone to E.164 form
17	 * (see {@link OwnerTelephone}), throwing {@link InvalidTelephoneException} (400) when it cannot form
18	 * a valid number. Publishes the normalized body for later steps.
19	 */
20	public class RequireOwnerFields {
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws MissingFieldsException, InvalidTelephoneException, InvalidEmailException {
24	        List<String> missing = new ArrayList<>();
25	        if (isBlank(request.getFirstName())) {
26	            missing.add("firstName");
27	        }
28	        if (isBlank(request.getLastName())) {
29	            missing.add("lastName");
30	        }
31	        if (isBlank(request.getAddress())) {
32	            missing.add("address");
33	        }
34	        if (isBlank(request.getCity())) {
35	            missing.add("city");
36	        }
37	        if (isBlank(request.getTelephone())) {
38	            missing.add("telephone");
39	        }
40	        if (!missing.isEmpty()) {
41	            throw new MissingFieldsException(missing);
42	        }
43	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
44	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
45	        validated.set(request);
46	    }
47	
48	    private static boolean isBlank(String value) {
49	        return value == null || value.isBlank();
50	    }
51	}
