35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    public String getAddress() {
64	        return this.address;
65	    }
66	
67	    public void setAddress(String address) {
68	        this.address = address;
69	    }
70	
71	    public String getCity() {
72	        return this.city;
73	    }
74	
75	    public void setCity(String city) {
76	        this.city = city;
77	    }
78	
79	    public String getTelephone() {
80	        return this.telephone;
81	    }
82	
83	    public void setTelephone(String telephone) {
84	        this.telephone = telephone;
85	    }
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    public void setEmail(String email) {
92	        this.email = email;
93	    }
94	
95	    public LocalDate getRegistrationDate() {
96	        return this.registrationDate;
97	    }
98	
99	    public void setRegistrationDate(LocalDate registrationDate) {
100	        this.registrationDate = registrationDate;
101	    }
102	
103	    public String getCustomerCode() {
104	        return this.customerCode;
105	    }
106	
107	    public void setCustomerCode(String customerCode) {
108	        this.customerCode = customerCode;
109	    }
110	
111	    protected Set<Pet> getPetsInternal() {
112	        if (this.pets == null) {
113	            this.pets = new HashSet<>();
114	        }
115	        return this.pets;
116	    }
117	
118	    protected void setPetsInternal(Set<Pet> pets) {
119	        this.pets = pets;
120	    }
121	
122	    public List<Pet> getPets() {
123	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
124	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
125	        return Collections.unmodifiableList(sortedPets);
126	    }
127	
128	    public void setPets(List<Pet> pets) {
129	        this.pets = new HashSet<>(pets);
130	    }
131	
132	    public void addPet(Pet pet) {
133	        getPetsInternal().add(pet);
134	        pet.setOwner(this);
135	    }
136	
137	    /**
138	     * Return the Pet with the given name, or null if none found for this Owner.
139	     *
140	     * @param name to test
141	     * @return true if pet name is already in use
142	     */
143	    public Pet getPet(String name) {
144	        return getPet(name, false);
145	    }
146	
147	    /**
148	     * Return the Pet with the given name, or null if none found for this Owner.
149	     *
150	     * @param name to test
151	     * @return true if pet name is already in use
152	     */
153	    public Pet getPet(String name, boolean ignoreNew) {
154	        name = name.toLowerCase();
155	        for (Pet pet : getPetsInternal()) {
156	            if (!ignoreNew || !pet.isNew()) {
157	                String compName = pet.getName();
158	                compName = compName.toLowerCase();
159	                if (compName.equals(name)) {
160	                    return pet;
161	                }
162	            }
163	        }
164	        return null;
165	    }
166	
167	    public Pet getPet(Integer petId) {
168	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
169	    }
170	
171	    @Override
172	    public String toString() {
173	        return new ToStringCreator(this)
174	
175	            .append("id", this.getId())
176	            .append("new", this.isNew())
177	            .append("lastName", this.getLastName())
178	            .append("firstName", this.getFirstName())
179	            .append("address", this.address)
180	            .append("city", this.city)
181	            .append("telephone", this.telephone)
182	            .toString();
183	    }
184	}
