7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
9	 * upper-cased first three letters of lastName and NNNN is a global 4-digit zero-padded sequence
10	 * equal to one more than the current number of owners (e.g. {@code SMI-0007}). Runs before
11	 * {@link SaveOwner} so the owner being created is not itself counted.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String lastName = owner.getLastName();
17	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
18	        int sequence = ownerRepository.findAll().size() + 1;
19	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
20	    }
21	}
