3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Shared normalization of an owner telephone to E.164 form. Spaces, dashes and brackets are
7	 * stripped. A leading {@code '+'} and its country code are kept as supplied; otherwise the default
8	 * country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
9	 * national digits. The result must carry 8 to 15 digits after the {@code '+'}, or the value is
10	 * rejected as invalid.
11	 *
12	 * <p>Examples: {@code "0412 345 678" -> "+61412345678"}, {@code "+64 21 123 456" -> "+6421123456"}.
13	 */
14	final class OwnerTelephone {
15	
16	    private OwnerTelephone() {
17	    }
18	
19	    /**
20	     * @return the canonical E.164 telephone (a {@code '+'} followed by 8-15 digits).
21	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
22	     */
23	    static String toE164(String telephone) throws InvalidTelephoneException {
24	        if (telephone == null) {
25	            throw invalid();
26	        }
27	        // Strip spaces, dashes and brackets; any other non-digit survives and fails the check below.
28	        String stripped = telephone.replaceAll("[\\s()\\-]", "");
29	        String e164;
30	        if (stripped.startsWith("+")) {
31	            e164 = "+" + stripped.substring(1);
32	        }
33	        else {
34	            String national = stripped;
35	            if (national.startsWith("0")) {
36	                national = national.substring(1);
37	            }
38	            e164 = "+61" + national;
39	        }
40	        String digits = e164.substring(1);
41	        if (!digits.matches("[0-9]{8,15}")) {
42	            throw invalid();
43	        }
44	        return e164;
45	    }
46	
47	    private static InvalidTelephoneException invalid() {
48	        return new InvalidTelephoneException(
49	                "Telephone must form a valid E.164 number with 8 to 15 digits after the country code");
50	    }
51	}
