1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
7	
8	/**
9	 * Shared normalization for the optional owner email. An email is optional: when absent (null or
10	 * blank) it is left as {@code null}. When present it must be a syntactically valid address; the
11	 * canonical stored/returned form is trimmed and lower-cased.
12	 */
13	final class OwnerEmail {
14	
15	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
16	
17	    private OwnerEmail() {
18	    }
19	
20	    /**
21	     * @return the normalized (trimmed, lower-cased) email, or {@code null} when none was supplied.
22	     * @throws InvalidEmailException when a non-blank value is not a valid address.
23	     */
24	    static String normalize(String email) throws InvalidEmailException {
25	        if (email == null || email.isBlank()) {
26	            return null;
27	        }
28	        String normalized = email.trim().toLowerCase(Locale.ROOT);
29	        if (!EMAIL.matcher(normalized).matches()) {
30	            throw new InvalidEmailException("Email must be a syntactically valid address");
31	        }
32	        return normalized;
33	    }
34	}
