11	
12	    private final List<String> fields;
13	
14	    public MissingFieldsException(List<String> fields) {
15	        super("Missing or blank required fields: " + String.join(", ", fields));
16	        this.fields = List.copyOf(fields);
17	    }
18	
19	    public List<String> getFields() {
20	        return this.fields;
21	    }
22	}
